 static object Sessions(bool clean){IntPtr data;uint count,total,resume=0;uint rc=NetSessionEnum(null,null,null,1,out data,0xffffffff,out count,out total,ref resume);var records=new List<object>();if(rc!=0)return new{ok=false,nativeError=rc,records=records};try{int size=Marshal.SizeOf(typeof(Session1));for(int i=0;i<count;i++){var s=(Session1)Marshal.PtrToStructure(new IntPtr(data.ToInt64()+i*size),typeof(Session1));string user=s.user??"";string shortUser=user.Substring(user.LastIndexOf('\\')+1);bool own=shortUser.Equals("ld_reader",StringComparison.OrdinalIgnoreCase)||shortUser.Equals("ld_denied",StringComparison.OrdinalIgnoreCase);uint? removed=null;if(clean&&own&&s.opens==0)removed=NetSessionDel(null,s.client,s.user);records.Add(new{client=s.client,user=s.user,openFiles=s.opens,labOwned=own,cleanupResult=removed});}}finally{NetApiBufferFree(data);}return new{ok=true,nativeError=rc,records=records};}
 static int Main(string[] args){try{bool admin=new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);if(!admin)throw new Exception("Administrator required");if(Environment.MachineName!="LD-PROJ-VM"&&Environment.MachineName!="ZHANGSH")throw new Exception("Wrong machine name");var networks=new List<object>();using(var q=new ManagementObjectSearcher("SELECT * FROM Win32_NetworkAdapterConfiguration WHERE IPEnabled=True"))foreach(ManagementObject n in q.Get())networks.Add(new{index=n["InterfaceIndex"],mac=n["MACAddress"],ips=n["IPAddress"],masks=n["IPSubnet"],gateways=n["DefaultIPGateway"],dns=n["DNSServerSearchOrder"],dhcp=n["DHCPEnabled"]});
 var routes=new List<object>();using(var q=new ManagementObjectSearcher("SELECT Destination,Mask,NextHop,InterfaceIndex FROM Win32_IP4RouteTable"))foreach(ManagementObject r in q.Get())routes.Add(new{destination=r["Destination"],mask=r["Mask"],nextHop=r["NextHop"],index=r["InterfaceIndex"]});
 IntPtr shareBuffer;uint shareRc=NetShareGetInfo(null,"AVEVAProjects",502,out shareBuffer);if(shareRc!=0)throw new Exception("Share inspection error="+shareRc);string sharePath,shareSddl;try{var share=(Share502)Marshal.PtrToStructure(shareBuffer,typeof(Share502));sharePath=share.path;byte[] bytes=new byte[GetSecurityDescriptorLength(share.sd)];Marshal.Copy(share.sd,bytes,0,bytes.Length);shareSddl=new RawSecurityDescriptor(bytes,0).GetSddlForm(AccessControlSections.Access);}finally{NetApiBufferFree(shareBuffer);}
 dynamic policy=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FwPolicy2"));dynamic rule=policy.Rules.Item("LaunchDeskLab-SMB-20261028-g0-g1");var firewall=new{enabled=(bool)rule.Enabled,protocol=(int)rule.Protocol,localPorts=(string)rule.LocalPorts,localAddresses=(string)rule.LocalAddresses,remoteAddresses=(string)rule.RemoteAddresses,profiles=(int)rule.Profiles,currentProfiles=(int)policy.CurrentProfileTypes,firewallDomainEnabled=(bool)policy.FirewallEnabled[1],firewallPrivateEnabled=(bool)policy.FirewallEnabled[2],firewallPublicEnabled=(bool)policy.FirewallEnabled[4]};
 var os=new List<object>();using(var q=new ManagementObjectSearcher("SELECT Caption,Version,BuildNumber FROM Win32_OperatingSystem"))foreach(ManagementObject item in q.Get())os.Add(new{caption=item["Caption"],version=item["Version"],build=item["BuildNumber"]});var accounts=new System.Collections.Generic.List<object>();using(var q=new ManagementObjectSearcher("SELECT Name,Domain,SID,Disabled,Lockout,PasswordExpires FROM Win32_UserAccount WHERE LocalAccount=True AND (Name=\u0027ld_reader\u0027 OR Name=\u0027ld_denied\u0027)"))foreach(ManagementObject a in q.Get())accounts.Add(new{name=a["Name"],domain=a["Domain"],sid=a["SID"],disabled=a["Disabled"],lockout=a["Lockout"],passwordExpires=a["PasswordExpires"]});object cleanup=Sessions(args.Length>0&&args[0]=="cleanup");File.WriteAllText(Out,Json.Serialize(new{ok=true,utc=DateTime.UtcNow.ToString("o"),computer=Environment.MachineName,user=WindowsIdentity.GetCurrent().Name,admin=admin,os=os,accounts=accounts,networks=networks,routes=routes,share=new{path=sharePath,sddl=shareSddl},ntfs=new{root=Directory.GetAccessControl(@"C:\LaunchDeskLab\AVEVAProjects").GetSecurityDescriptorSddlForm(AccessControlSections.Access),denied=Directory.GetAccessControl(@"C:\LaunchDeskLab\AVEVAProjects\Denied").GetSecurityDescriptorSddlForm(AccessControlSections.Access)},firewall=firewall,sessions=cleanup}));return 0;
 }catch(Exception e){File.WriteAllText(Out,Json.Serialize(new{ok=false,error=e.Message}));return 1;}}
